1	import { DatabaseSync } from "node:sqlite";
2	import { randomUUID } from "node:crypto";
3	import { mkdirSync, readFileSync } from "node:fs";
4	import { dirname } from "node:path";
5	import { Group } from "@semaphore-protocol/group";
6	import type { GroupVersionSummary, PollDetail, PollResults, PollSummary, VoteReceipt } from "./types.ts";
7	
8	interface SeedPoll extends Omit<PollDetail, "memberCount" | "optionCount" | "eligibleMemberCommitments" | "groupVersion" | "merkleRoot"> {}
9	interface CatalogSeed { polls: SeedPoll[]; memberCommitments: string[] }
10	interface PollRow {
11	  id: string; title: string; summary: string; description: string;
12	  organizer: string; status: "open"; published_at: string; closes_at: string;
13	  options_json: string; group_version: number; frozen_version: number | null;
14	}
15	interface GroupVersionRow { poll_id: string; version: number; commitments_json: string; merkle_root: string; created_at: string }
16	interface VoteRow { id: string; poll_id: string; option_id: string; nullifier: string; accepted_at: string }
17	
18	export interface GroupSnapshot { version: number; commitments: string[]; merkleRoot: string }
19	export type GroupOperation =
20	  | { type: "join"; commitment: string }
21	  | { type: "rotate"; oldCommitment: string; newCommitment: string }
22	  | { type: "revoke"; commitment: string };
23	export type GroupOperationOutcome =
24	  | { ok: true; group: GroupVersionSummary }
25	  | { ok: false; reason: "poll_missing" | "group_frozen" | "group_version_changed" | "duplicate_commitment" | "commitment_not_found" | "empty_group" };
26	export type CommitVoteOutcome =
27	  | { ok: true; receipt: VoteReceipt }
28	  | { ok: false; reason: "poll_closed" | "invalid_option" | "duplicate_nullifier" | "group_version_changed" };
29	
30	function toReceipt(row: VoteRow): VoteReceipt {
31	  return { id: row.id, pollId: row.poll_id, optionId: row.option_id, nullifier: row.nullifier, acceptedAt: row.accepted_at };
32	}
33	function toSnapshot(row: GroupVersionRow): GroupSnapshot {
34	  return { version: row.version, commitments: JSON.parse(row.commitments_json) as string[], merkleRoot: row.merkle_root };
35	}
36	function merkleRootOf(commitments: string[]): string {
37	  return new Group(commitments).root.toString();
38	}
39	
40	export function openCatalog(databasePath: string) {
41	  if (databasePath !== ":memory:") mkdirSync(dirname(databasePath), { recursive: true });
42	  const db = new DatabaseSync(databasePath);
43	  db.exec(`
44	    PRAGMA foreign_keys = ON;
45	    PRAGMA journal_mode = WAL;
46	    CREATE TABLE IF NOT EXISTS polls (
47	      id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
48	      description TEXT NOT NULL, organizer TEXT NOT NULL, status TEXT NOT NULL,
49	      published_at TEXT NOT NULL, closes_at TEXT NOT NULL, options_json TEXT NOT NULL
50	    );
51	    CREATE TABLE IF NOT EXISTS members (
52	      commitment TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE
53	    );
54	    CREATE TABLE IF NOT EXISTS votes (
55	      id TEXT PRIMARY KEY,
56	      poll_id TEXT NOT NULL REFERENCES polls (id),
57	      option_id TEXT NOT NULL,
58	      nullifier TEXT NOT NULL,
59	      accepted_at TEXT NOT NULL
60	    );
61	    CREATE UNIQUE INDEX IF NOT EXISTS votes_poll_nullifier ON votes (poll_id, nullifier);
62	    CREATE TABLE IF NOT EXISTS group_versions (
63	      poll_id TEXT NOT NULL REFERENCES polls (id),
64	      version INTEGER NOT NULL,
65	      commitments_json TEXT NOT NULL,
66	      merkle_root TEXT NOT NULL,
67	      created_at TEXT NOT NULL,
68	      PRIMARY KEY (poll_id, version)
69	    );
70	    CREATE INDEX IF NOT EXISTS group_versions_root ON group_versions (poll_id, merkle_root);
71	  `);
72	  // Migrate pre-versioning databases: add the group columns to existing polls.
73	  const pollColumns = new Set((db.prepare("PRAGMA table_info(polls)").all() as { name: string }[]).map(column => column.name));
74	  if (!pollColumns.has("group_version")) db.exec("ALTER TABLE polls ADD COLUMN group_version INTEGER NOT NULL DEFAULT 1");
75	  if (!pollColumns.has("frozen_version")) db.exec("ALTER TABLE polls ADD COLUMN frozen_version INTEGER");
76	
77	  const existing = db.prepare("SELECT count(*) AS count FROM polls").get() as { count: number };
78	  if (existing.count === 0) {
79	    const seed = JSON.parse(readFileSync(new URL("../fixtures/catalog.json", import.meta.url), "utf8")) as CatalogSeed;
80	    db.exec("BEGIN");
81	    try {
82	      const insertPoll = db.prepare("INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
83	      for (const poll of seed.polls) insertPoll.run(poll.id, poll.title, poll.summary, poll.description, poll.organizer, poll.status, poll.publishedAt, poll.closesAt, JSON.stringify(poll.options));
84	      const insertMember = db.prepare("INSERT INTO members VALUES (?, ?)");
85	      seed.memberCommitments.forEach((commitment, index) => insertMember.run(commitment, index));
86	      db.exec("COMMIT");
87	    } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
88	  }
89	  // Snapshot the legacy member list as immutable version 1 for every poll that
90	  // has no versions yet (fresh seeds and databases migrated from before
91	  // versioned groups). The snapshot, its Merkle root and the version number
92	  // are persisted together so all three stay consistent across restarts.
93	  const versioned = db.prepare("SELECT count(*) AS count FROM group_versions").get() as { count: number };
94	  if (versioned.count === 0) {
95	    const commitments = members();
96	    if (commitments.length > 0) {
97	      const merkleRoot = merkleRootOf(commitments);
98	      const createdAt = new Date().toISOString();
99	      const insertVersion = db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, 1, ?, ?, ?)");
100	      const pollIds = db.prepare("SELECT id FROM polls").all() as { id: string }[];
101	      db.exec("BEGIN");
102	      try {
103	        for (const poll of pollIds) insertVersion.run(poll.id, JSON.stringify(commitments), merkleRoot, createdAt);
104	        // Polls that already accepted votes are frozen on version 1, matching
105	        // the freeze-on-first-vote rule applied to new votes.
106	        db.exec("UPDATE polls SET frozen_version = 1 WHERE frozen_version IS NULL AND id IN (SELECT DISTINCT poll_id FROM votes)");
107	        db.exec("COMMIT");
108	      } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
109	    }
110	  }
111	
112	  function members(): string[] {
113	    return (db.prepare("SELECT commitment FROM members ORDER BY position").all() as { commitment: string }[]).map(row => row.commitment);
114	  }
115	  function pollRow(id: string): PollRow | undefined {
116	    return db.prepare("SELECT * FROM polls WHERE id = ?").get(id) as PollRow | undefined;
117	  }
118	  function isOpen(row: PollRow, now: number): boolean {
119	    return row.status === "open" && now < Date.parse(row.closes_at);
120	  }
121	  function currentSnapshot(pollId: string): GroupSnapshot | undefined {
122	    const row = db.prepare(`
123	      SELECT gv.* FROM polls p
124	      JOIN group_versions gv ON gv.poll_id = p.id AND gv.version = p.group_version
125	      WHERE p.id = ?
126	    `).get(pollId) as GroupVersionRow | undefined;
127	    return row ? toSnapshot(row) : undefined;
128	  }
129	  function summarize(row: PollRow): PollSummary {
130	    return {
131	      id: row.id, title: row.title, summary: row.summary, organizer: row.organizer,
132	      status: row.status, publishedAt: row.published_at, closesAt: row.closes_at,
133	      memberCount: currentSnapshot(row.id)?.commitments.length ?? 0, optionCount: JSON.parse(row.options_json).length
134	    };
135	  }
136	  return {
137	    list(): PollSummary[] {
138	      return (db.prepare("SELECT * FROM polls ORDER BY published_at DESC, id").all() as unknown as PollRow[]).map(summarize);
139	    },
140	    get(id: string): PollDetail | undefined {
141	      const row = pollRow(id);
142	      if (!row) return undefined;
143	      const snapshot = currentSnapshot(id);
144	      if (!snapshot) return undefined;
145	      return {
146	        ...summarize(row), description: row.description, options: JSON.parse(row.options_json),
147	        eligibleMemberCommitments: snapshot.commitments, groupVersion: snapshot.version, merkleRoot: snapshot.merkleRoot
148	      };
149	    },
150	    /** The immutable snapshot a poll currently points at, or a specific historical version. */
151	    groupSnapshot(pollId: string, version?: number): GroupSnapshot | undefined {
152	      if (version === undefined) return currentSnapshot(pollId);
153	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND version = ?").get(pollId, version) as GroupVersionRow | undefined;
154	      return row ? toSnapshot(row) : undefined;
155	    },
156	    /** The snapshot whose Merkle root matches, used to place proofs from clients that omit groupVersion. */
157	    groupSnapshotByRoot(pollId: string, merkleRoot: string): GroupSnapshot | undefined {
158	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND merkle_root = ? ORDER BY version DESC LIMIT 1").get(pollId, merkleRoot) as GroupVersionRow | undefined;
159	      return row ? toSnapshot(row) : undefined;
160	    },
161	    /**
162	     * Applies a membership change as a new immutable version. The optimistic
163	     * expectedVersion check, the frozen check and the pointer update happen in
164	     * one immediate transaction, so a concurrent vote either freezes the group
165	     * first (this then fails with group_frozen) or observes the new version.
166	     */
167	    applyGroupOperation(pollId: string, operation: GroupOperation, expectedVersion: number): GroupOperationOutcome {
168	      db.exec("BEGIN IMMEDIATE");
169	      try {
170	        const row = pollRow(pollId);
171	        if (!row) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_missing" }; }
172	        if (row.frozen_version !== null) { db.exec("ROLLBACK"); return { ok: false, reason: "group_frozen" }; }
173	        if (row.group_version !== expectedVersion) { db.exec("ROLLBACK"); return { ok: false, reason: "group_version_changed" }; }
174	        const snapshot = currentSnapshot(pollId);
175	        if (!snapshot) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_missing" }; }
176	        const commitments = [...snapshot.commitments];
177	        if (operation.type === "join") {
178	          if (commitments.includes(operation.commitment)) { db.exec("ROLLBACK"); return { ok: false, reason: "duplicate_commitment" }; }
179	          commitments.push(operation.commitment);
180	        } else if (operation.type === "rotate") {
181	          const index = commitments.indexOf(operation.oldCommitment);
182	          if (index === -1) { db.exec("ROLLBACK"); return { ok: false, reason: "commitment_not_found" }; }
183	          if (commitments.includes(operation.newCommitment)) { db.exec("ROLLBACK"); return { ok: false, reason: "duplicate_commitment" }; }
184	          commitments[index] = operation.newCommitment;
185	        } else {
186	          const index = commitments.indexOf(operation.commitment);
187	          if (index === -1) { db.exec("ROLLBACK"); return { ok: false, reason: "commitment_not_found" }; }
188	          if (commitments.length === 1) { db.exec("ROLLBACK"); return { ok: false, reason: "empty_group" }; }
189	          commitments.splice(index, 1);
190	        }
191	        const version = expectedVersion + 1;
192	        const merkleRoot = merkleRootOf(commitments);
193	        db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, ?, ?, ?, ?)")
194	          .run(pollId, version, JSON.stringify(commitments), merkleRoot, new Date().toISOString());
195	        db.prepare("UPDATE polls SET group_version = ? WHERE id = ?").run(version, pollId);
196	        db.exec("COMMIT");
197	        return { ok: true, group: { pollId, version, merkleRoot, memberCount: commitments.length, commitments } };
198	      } catch (error) {
199	        db.exec("ROLLBACK");
200	        throw error;
201	      }
202	    },
203	    /**
204	     * Re-validates the poll state, confirms the group version is still current,
205	     * freezes that version on the first accepted vote, rejects a reused
206	     * nullifier and persists the vote in a single immediate transaction; the
207	     * UNIQUE (poll_id, nullifier) index is the backstop against concurrent
208	     * duplicates and deduplicates across versions.
209	     */
210	    commitVote(pollId: string, optionId: string, nullifier: string, groupVersion: number, now = Date.now()): CommitVoteOutcome {
211	      db.exec("BEGIN IMMEDIATE");
212	      try {
213	        const row = pollRow(pollId);
214	        if (!row || !isOpen(row, now)) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_closed" }; }
215	        if (row.group_version !== groupVersion) { db.exec("ROLLBACK"); return { ok: false, reason: "group_version_changed" }; }
216	        const options = JSON.parse(row.options_json) as { id: string }[];
217	        if (!options.some(option => option.id === optionId)) { db.exec("ROLLBACK"); return { ok: false, reason: "invalid_option" }; }
218	        const duplicate = db.prepare("SELECT 1 AS found FROM votes WHERE poll_id = ? AND nullifier = ?").get(pollId, nullifier);
219	        if (duplicate) { db.exec("ROLLBACK"); return { ok: false, reason: "duplicate_nullifier" }; }
220	        const receipt: VoteReceipt = { id: randomUUID(), pollId, optionId, nullifier, acceptedAt: new Date(now).toISOString() };
221	        db.prepare("INSERT INTO votes (id, poll_id, option_id, nullifier, accepted_at) VALUES (?, ?, ?, ?, ?)")
222	          .run(receipt.id, receipt.pollId, receipt.optionId, receipt.nullifier, receipt.acceptedAt);
223	        if (row.frozen_version === null) db.prepare("UPDATE polls SET frozen_version = ? WHERE id = ?").run(groupVersion, pollId);
224	        db.exec("COMMIT");
225	        return { ok: true, receipt };
226	      } catch (error) {
227	        db.exec("ROLLBACK");
228	        if (error instanceof Error && error.message.includes("UNIQUE")) return { ok: false, reason: "duplicate_nullifier" };
229	        throw error;
230	      }
231	    },
232	    results(pollId: string): PollResults | undefined {
233	      const row = pollRow(pollId);
234	      if (!row) return undefined;
235	      const counts = new Map(
236	        (db.prepare("SELECT option_id, count(*) AS count FROM votes WHERE poll_id = ? GROUP BY option_id").all(pollId) as { option_id: string; count: number }[])
237	          .map(entry => [entry.option_id, entry.count])
238	      );
239	      const options = (JSON.parse(row.options_json) as { id: string }[]).map(option => ({ id: option.id, count: counts.get(option.id) ?? 0 }));
240	      return { pollId, total: options.reduce((sum, option) => sum + option.count, 0), options };
241	    },
242	    receipt(id: string): VoteReceipt | undefined {
243	      const row = db.prepare("SELECT * FROM votes WHERE id = ?").get(id) as VoteRow | undefined;
244	      return row ? toReceipt(row) : undefined;
245	    },
246	    close() { db.close(); }
247	  };
248	}
249

