30	async function pollDetail(base: string, id: string): Promise<PollDetail> {
31	  const response = await fetch(`${base}/api/polls/${encodeURIComponent(id)}`);
32	  assert.equal(response.status, 200);
33	  return ((await response.json()) as { poll: PollDetail }).poll;
