72	    assert.equal((await postGroup(base, poll.id, { operation: "join", expectedVersion: "1", commitment: "5" })).status, 400);
73	    assert.equal((await postGroup(base, poll.id, { operation: "join", expectedVersion: 1, commitment: "not-a-commitment" })).status, 400);
74	    assert.equal((await fetch(`${base}/api/polls/${poll.id}/group`)).status, 405);
75	
76	    // join appends and bumps the version.
77	    const joiner = commitmentOf("veilvote-demo-member-09");
78	    const joined = await postGroup(base, poll.id, { operation: "join", expectedVersion: 1, commitment: joiner });
79	    assert.equal(joined.status, 201);
80	    assert.equal(joined.body.group!.version, 2);
81	    assert.equal(joined.body.group!.memberCount, 9);
82	    assert.notEqual(joined.body.group!.merkleRoot, poll.merkleRoot);
83	    assert.equal(joined.body.group!.commitments.at(-1), joiner);
84	    // Duplicate commitments are rejected.
85	    const duplicate = await postGroup(base, poll.id, { operation: "join", expectedVersion: 2, commitment: joiner });
86	    assert.equal(duplicate.status, 400);
87	    assert.equal(duplicate.body.error, "duplicate_commitment");
88	    // Stale expectedVersion conflicts.
89	    const stale = await postGroup(base, poll.id, { operation: "join", expectedVersion: 1, commitment: commitmentOf("veilvote-demo-member-10") });
90	    assert.equal(stale.status, 409);
91	    assert.equal(stale.body.error, "group_version_changed");
