93	    // rotate replaces in place.
94	    const rotatedTo = commitmentOf("veilvote-demo-member-10");
95	    const rotated = await postGroup(base, poll.id, { operation: "rotate", expectedVersion: 2, oldCommitment: joiner, newCommitment: rotatedTo });
96	    assert.equal(rotated.status, 201);
97	    assert.equal(rotated.body.group!.version, 3);
98	    assert.equal(rotated.body.group!.memberCount, 9);
99	    assert.equal(rotated.body.group!.commitments[8], rotatedTo);
100	    assert.ok(!rotated.body.group!.commitments.includes(joiner));
101	    // rotate with an unknown old commitment or an existing new one fails.
102	    assert.equal((await postGroup(base, poll.id, { operation: "rotate", expectedVersion: 3, oldCommitment: joiner, newCommitment: "7" })).body.error, "commitment_not_found");
103	    assert.equal((await postGroup(base, poll.id, { operation: "rotate", expectedVersion: 3, oldCommitment: rotatedTo, newCommitment: poll.eligibleMemberCommitments[0] })).body.error, "duplicate_commitment");
104	
105	    // revoke removes; the detail endpoint reflects the current version.
106	    const revoked = await postGroup(base, poll.id, { operation: "revoke", expectedVersion: 3, commitment: rotatedTo });
107	    assert.equal(revoked.status, 201);
108	    assert.equal(revoked.body.group!.version, 4);
109	    assert.deepEqual(revoked.body.group!.commitments, poll.eligibleMemberCommitments);
110	    assert.equal(revoked.body.group!.merkleRoot, poll.merkleRoot);
111	    const detail = await pollDetail(base, poll.id);
112	    assert.equal(detail.groupVersion, 4);
113	    assert.equal(detail.merkleRoot, poll.merkleRoot);
114	    assert.deepEqual(detail.eligibleMemberCommitments, poll.eligibleMemberCommitments);
115	    assert.equal((await postGroup(base, poll.id, { operation: "revoke", expectedVersion: 4, commitment: rotatedTo })).body.error, "commitment_not_found");
116	
117	    // The group may not be emptied: revoke the other poll down to one member.
118	    const other = await pollDetail(base, "shared-space-improvement");
119	    let version = other.groupVersion;
