204	    const staleExplicit = await postVote(base, poll.id, { optionId: optionA.id, groupVersion: 1, proof: v1Proof });
205	    assert.equal(staleExplicit.status, 409);
206	    assert.equal(staleExplicit.body.error, "group_version_changed");
207	    const staleByRoot = await postVote(base, poll.id, { optionId: optionA.id, proof: v1Proof });
208	    assert.equal(staleByRoot.status, 409);
209	    assert.equal(staleByRoot.body.error, "group_version_changed");
210	    // Declaring the current version while carrying the old root is a binding mismatch.
211	    const mismatched = await postVote(base, poll.id, { optionId: optionA.id, groupVersion: 2, proof: v1Proof });
212	    assert.equal(mismatched.status, 422);
213	    assert.equal(mismatched.body.error, "proof_binding_mismatch");
214	    // A root no version ever had is unprocessable.
215	    const stranger = new Identity("veilvote-stranger");
216	    const strangerProof = await generateProof(stranger, new Group([stranger.commitment.toString()]), optionA.id, poll.id) as SemaphoreProofPayload;
217	    const unknown = await postVote(base, poll.id, { optionId: optionA.id, proof: strangerProof });
218	    assert.equal(unknown.status, 422);
219	    assert.equal(unknown.body.error, "unknown_merkle_root");
220	
221	    // Legacy clients (no groupVersion) vote against the current version by root resolution.
222	    const current = await pollDetail(base, poll.id);
223	    assert.equal(current.groupVersion, 2);
224	    const v2Proof = await proofFor("veilvote-demo-member-01", optionA.id, current);
225	    const accepted = await postVote(base, poll.id, { optionId: optionA.id, proof: v2Proof });
226	    assert.equal(accepted.status, 201);
227	    assert.equal(accepted.body.receipt!.nullifier, v2Proof.nullifier);
