229	    // The first accepted vote froze version 2: further changes are rejected.
230	    const frozen = await postGroup(base, poll.id, { operation: "join", expectedVersion: 2, commitment: commitmentOf("veilvote-demo-member-10") });
231	    assert.equal(frozen.status, 409);
232	    assert.equal(frozen.body.error, "group_frozen");
233	
234	    // Dedup still works on the frozen version, with an explicit version.
235	    const replay = await postVote(base, poll.id, { optionId: optionB.id, groupVersion: 2, proof: await proofFor("veilvote-demo-member-01", optionB.id, current) });
236	    assert.equal(replay.status, 409);
237	    assert.equal(replay.body.error, "duplicate_nullifier");
238	  } finally {
239	    await stop(server);
240	  }
241	});
