24	  duplicate_nullifier: "该身份已在此议题投过票（重复提交被拒绝）",
25	  invalid_proof: "证明无效，投票被拒绝",
26	  proof_binding_mismatch: "证明与议题或选项不匹配，投票被拒绝",
27	  group_version_changed: "成员名单已变更，请基于最新版本重新生成证明",
