129	      status.className = "vote-status ok";
130	      const receiptList = document.createElement("dl");
131	      for (const [label, value] of [["回执编号", receipt.id], ["议题", receipt.pollId], ["选项", receipt.optionId], ["Nullifier", receipt.nullifier], ["接受时间", receipt.acceptedAt]]) {
132	        receiptList.append(text("dt", label), text("dd", value));
