181	    commitments.append(rootLine);
182	    poll.eligibleMemberCommitments.forEach(commitment => commitments.append(text("code", commitment)));
183	    detail.replaceChildren(heading, text("h2", poll.title), text("p", poll.description, "description"), text("p", `议题组织方 / ${poll.organizer}`, "organizer"), stats, text("h3", "议题方案"), options, commitments, voteSection(poll));
184	  } catch (error) { if (selected === id) detail.replaceChildren(text("p", error instanceof Error ? error.message : "暂时无法读取议题", "error")); }
