transitionStatus(pollId: string, target: PollStatus, expectedStatus: PollStatus, now = Date.now()): StatusTransitionOutcome {
  db.exec("BEGIN IMMEDIATE");
  try {
    const row = pollRow(pollId);
    if (!row) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_missing" }; }
    if (!STATUSES.includes(target)) { db.exec("ROLLBACK"); return { ok: false, reason: "invalid_status" }; }
    if (row.status !== expectedStatus) {
      db.exec("ROLLBACK");
      recordAudit("status_change_rejected", pollId, "failure", { requested: target, expected: expectedStatus, actual: row.status, reason: "status_conflict" }, now);
      return { ok: false, reason: "status_conflict" };
    }
    if (STATUS_FLOW[row.status] !== target) {
      db.exec("ROLLBACK");
      recordAudit("status_change_rejected", pollId, "failure", { requested: target, expected: expectedStatus, actual: row.status, reason: "illegal_transition" }, now);
      return { ok: false, reason: "illegal_transition" };
    }
    const at = new Date(now).toISOString();
    db.prepare("UPDATE polls SET status = ? WHERE id = ?").run(target, pollId);
    insertAudit("poll_status_change", pollId, "success", { from: row.status, "to: target }, at);
    db.exec("COMMIT");
    return { ok: true, status: target };
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
},

