168	  function pollRow(id: string): PollRow | undefined {
169	    return db.prepare("SELECT * FROM polls WHERE id = ?").get(id) as PollRow | undefined;
170	  }
171	  /** A poll accepts votes only while open and before its deadline. */
172	  function isVotable(row: PollRow, now: number): boolean {
173	    return row.status === "open" && now < Date.parse(row.closes_at);
174	  }
175	  /**
176	   * Lazily persists the deadline transition for every open poll whose
177	   * closesAt has passed. Each status change and its audit row commit in one
178	   * transaction; a no-op read starts no write transaction. commitVote repeats
179	   * this check inside its own transaction, which is the authoritative
180	   * adjudication for a vote racing the cutoff.
181	   */
182	  function closeExpired(now = Date.now()) {
183	    const open = db.prepare("SELECT id, closes_at FROM polls WHERE status = 'open'").all() as { id: string; closes_at: string }[];
184	    const due = open.filter(row => now >= Date.parse(row.closes_at)).map(row => row.id);
185	    if (due.length === 0) return;
186	    db.exec("BEGIN IMMEDIATE");
